SELECT rm.JOB_ID jobId , rm.JOB_STATUS jobStatus , rm.PRO_ID proId , rm.PRO_NAME proName , rm.END_DATE endDate , rm.NEXT_DATE nextDate, rj.JOB_NAME jobName, info.report_name reportName, to_char(rm.END_DATE,'yyyy-mm-dd') endDateStr, to_char(rm.NEXT_DATE,'yyyy-mm-dd') nextDateStr FROM rep_monitor rm left join rep_job rj on rj.JOB_ID = rm.JOB_ID LEFT JOIN rep_info info ON info.rep_id = rj.rep_id WHERE 1=1
AND rm.JOB_ID IN
#{item}
AND rm.PRO_ID IN
#{item}
AND to_char(rm.END_DATE,'yyyy-mm-dd') >= #{valDateBegin,jdbcType=VARCHAR}
AND to_char(rm.END_DATE,'yyyy-mm-dd') <= #{valDateEnd,jdbcType=VARCHAR}

mapper.update:
      update REP_REVEAL
      set 
      CONFIRM_STATUS = #{confirmStatus,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = sysdate
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

mapper.select:
SELECT ril.JOB_ID jobId, ril.JOB_NAME jobName, ril.EXEC_STATUS execStatus, ril.EXEC_DATE execDate, to_char(ril.START_DATE,'yyyy-mm-dd hh24:mi:ss') startExecDate, to_char(ril.END_DATE,'yyyy-mm-dd hh24:mi:ss') endExecDate, ril.JOB_SEQ jobSeq, ril.EXEC_RESULT execResult, nvl(ril.EXEC_DETAIL,'') execResultExplain, to_char(ril.LASTEXEC_DATE,'yyyy-mm-dd hh24:mi:ss') lastexecDate
FROM REP_INSTALL_LOG ril WHERE ril.STATUS = #{status,jdbcType=VARCHAR}
AND ril.JOB_ID IN
#{item}
AND ril.EXEC_STATUS IN
#{item}
AND to_char(ril.START_DATE,'yyyy-mm-dd') >= #{valDateBegin,jdbcType=VARCHAR}
AND to_char(ril.START_DATE,'yyyy-mm-dd') <= #{valDateEnd,jdbcType=VARCHAR}
AND ril.EXEC_RESULT IN
#{item}
order by ril.EXEC_STATUS,ril.UPDATE_TIME desc
